import {hazardGrowth} from './modes.js';
import {battleRecord} from './chronicle.js';
import {DATA} from './data.js';
import {BY_ID,CARDS,evolvedCard,npcCard} from './cards.js';
import {freshSeed,hiddenChance,seedNumber,weighted,random,rollStat,derive,newAxis,grow,AXES,copy,value,score,ANCHORS,tierLabel} from './math.js';
import {newBattle,spawn,cardOf} from './battle.js';
import {HOSTS,tuneSummon} from './summons.js';
export const VERSION=3,STORAGE_KEY='terra-fate-v1';
export const STEPS=['出生地','种族','感染身份','穿越时间点','源石技艺','生理耐受','物理强度','战斗技巧','源石技艺强度','源石技艺适应性','成长天赋'];
export const TRANSITION=[12,10,10,12,10,30,16,14,12,12,10];
export const TRAINING=[{name:'稳步训练',weight:40,main:.04},{name:'动作精进',weight:25,main:.07},{name:'训练领悟',weight:10,main:.12},{name:'交叉训练',weight:15,main:.04,secondary:.02},{name:'全面校准',weight:5,all:.015},{name:'恢复调整',weight:5,lowest:.02,heal:.3}];
export function createRun({seed=freshSeed(),name='博士',mode='campaign',iron=false,legend=false,solo=false,hazard=false,node='random'}={}){return {version:VERSION,id:seed+'-'+Date.now().toString(36),rng:seedNumber(seed),seed,name:String(name).trim().slice(0,20)||'博士',mode,iron,legend,solo:!!solo,hazard:!!hazard,selectedNode:node,phase:'creation',step:0,rolls:[],axes:[],mastery:0,art:null,supply:6,intel:0,day:0,days:0,reserved:0,retried:false,battleIndex:0,nodeIndex:0,startNode:0,history:[],ledger:[],dailyHistory:[],specialization:'',extreme:false,summonMode:0,helpSeen:false};}
export function drawNext(s){if(s.phase!=='creation'||s.step>=11)throw Error('建角转盘已结束');let i=s.step,row;
 if(i===0)row=weighted(s,DATA.origins.birthplaces);
 if(i===1)row=weighted(s,DATA.origins.races);
 if(i===2)row=weighted(s,DATA.origins.identities);
 if(i===3)row=s.selectedNode==='random'?weighted(s,DATA.campaign.nodes,'entry_weight'):DATA.campaign.nodes.find(n=>n.id===s.selectedNode);
 if(i===4){let hidden=random(s)<hiddenChance(s.legend);row=weighted(s,CARDS.filter(c=>c.pool===(hidden?'hidden':'normal')));}
 if(i>=5&&i<=9){let value=rollStat(s);row={id:'axis-'+(i-5),name:STEPS[i],score:value};}
 if(i===10)row=weighted(s,DATA.talents.grades);
 const result={step:i,id:row.id||row.grade,name:i===4?row.name+'（'+row.source+'）':row.name||row.source||row.grade,score:row.score,grade:row.grade,multiplier:row.training_multiplier,source:row.source,pool:row.pool};
 s.rolls.push(result);s.step++;
 if(s.step===11){s.axes=s.rolls.slice(5,10).map(r=>newAxis(r.score));s.art=s.rolls[4].id;s.identity=s.rolls[2].id;s.talent=s.rolls[10].id;s.multiplier=s.rolls[10].multiplier;s.nodeIndex=DATA.campaign.nodes.findIndex(n=>n.id===s.rolls[3].id);s.startNode=s.nodeIndex;s.stats=derive(s.axes.map(a=>a.score),s.identity);s.hp=s.stats.H;s.startStats=copy(s.stats);s.phase='confirm';}
 return result;}
export function nodeOf(s){if(s.mode==='sandbox')return{id:'SIM',name:'PRTS模拟作战',battles:[s.trainingSpec]};return DATA.campaign.nodes[s.nodeIndex];}
export function enterNode(s,initial=false){let node=nodeOf(s);s.phase='camp';s.days=initial?[20,18,18,16,16,14,30,24,22,20,18,16][s.nodeIndex]:TRANSITION[s.nodeIndex-1]||0;s.battleIndex=0;s.retried=false;s.reserved=0;s.planClaimed=false;s.nodeSuccess=true;s.firstAid=false;s.battle=null;s.hp=Math.min(s.stats.H,s.hp);s.nodeIntro=true;s.allyHP={};s.carriedCoolers=[];}
export function reserveDay(s){if(s.phase!=='camp'||s.days<1||s.reserved||s.iron)throw Error('无法预留应急日');s.days--;s.reserved=1;}
export function recalc(s){let proportion=s.hp/s.stats.H;s.stats=derive(s.axes.map(a=>a.score),s.identity);s.hp=Math.max(1,Math.floor(s.stats.H*proportion));}
export const DAILY_PROJECTS=[
 {name:'体质锻炼',axis:0,weight:16},{name:'力量锻炼',axis:1,weight:14},{name:'体术训练',axis:2,weight:14},
 {name:'源石技艺修行',axis:3,m:5,weight:18},{name:'适应性研习',axis:4,m:2,weight:14},
 {name:'矢量突破',vector:true,weight:16},{name:'物资检整',supply:2,weight:4}];
export function growth(s,indices,base,mult,event,source='training',proof=0){const before={...s.stats},rows=[];const modeMult=hazardGrowth(s),talentMult=mult;mult*=modeMult;
 for(const i of indices){const old=s.axes[i].score,requested=base*mult,delta=score(value(old)+requested)-old;
  grow(s.axes[i],Math.max(0,delta),event,source,proof);rows.push({axis:i,base,mult,modeMult,talentMult,factor:source==='training'?(old<10?1:old<12?.15:old<14?.04:.01):1,actual:value(s.axes[i].score)-value(old)});}
 recalc(s);for(const row of rows){const keys=[['H'],['D'],['A'],['P'],['R','Emax']][row.axis];row.values=keys.map(k=>({key:k,before:before[k],after:s.stats[k],gain:s.stats[k]-before[k]}));}return rows;
}
export function train(s){if(s.phase!=='camp'||s.days<=0)throw Error('没有可用准备日');
 const row=weighted(s,DAILY_PROJECTS),quality=weighted(s,[{name:'稳步积累',base:6,weight:55},{name:'动作精进',base:9,weight:30},{name:'训练领悟',base:14,weight:15}]);
 const before=snapshot(s);let result={type:row.vector?'vector':'daily',day:s.day+1,name:row.name,quality:quality.name,masteryBefore:s.mastery,mult:s.multiplier*hazardGrowth(s),gains:[],mastery:0};
 const event=s.id+':day:'+s.day;s.day++;s.days--;
 if(row.vector){s.pendingTraining=result;s.trainingSpec=null;s.phase='vectorPrep';
 }else{if(row.axis!==undefined)result.gains=growth(s,[row.axis],quality.base,s.multiplier,event);
  if(row.m){const before=s.mastery;s.mastery=Math.min(200,s.mastery+row.m);result.mastery=s.mastery-before;result.masteryBase=row.m;result.masteryMultiplier=1;}
  if(row.supply){s.supply+=row.supply;result.supply=row.supply;}s.dailyHistory.push(result);}
 if(!row.vector){s.hp=s.stats.H;result.recovered=true;s.pendingTrainingGrowth={...result,title:result.name,before,after:snapshot(s)};}s.lastDaily=result;return result;
}
export function drawVectorArt(s){if(s.phase!=='vectorPrep')throw Error('不是突破抽取阶段');const r=s.pendingTraining;if(r.art)return r.art;const pool=CARDS.filter(c=>c.pool==='normal'&&/^[3-6]星$/.test(DATA.arts.cards.find(x=>x.art_id===c.id)?.source_rarity));const art=weighted(s,pool.map(c=>({...c,weight:1})));r.art=art.id;r.name='矢量突破 · '+art.name+'（'+art.source+'）';prepareVector(s);return r.art;}
export function drawVectorTier(s){if(s.phase!=='vectorPrep')throw Error('不是突破抽取阶段');const r=s.pendingTraining;if(r.enemyTier!==undefined)return r.enemyTier;const tier=Math.floor(s.stats.rating.score),lower=Array.from({length:tier},(_,i)=>({tier:tier-i-1,weight:[20,12,8,5,3,2][i]||1}));r.enemyTier=tier===0||random(s)<.5?tier:weighted(s,lower).tier;prepareVector(s);return r.enemyTier;}
function prepareVector(s){const r=s.pendingTraining;if(!r.art||r.enemyTier===undefined)return;const art=BY_ID[r.art];s.trainingSpec={id:'VECTOR',title:'矢量突破 · '+art.source,allies:[],enemies:[],customUnits:[{id:'projection',name:art.source+' · 训练投影',art:art.id,mastery:s.mastery,stats:derive(Array(5).fill(r.enemyTier))}],goal:'击败训练投影；博士退场后存活友方继续作战。120轮防僵局，18轮起力竭。',mechanic:''};}
export function beginVector(s){if(s.phase!=='vectorPrep')throw Error('尚未抽取训练对手');if(!s.trainingSpec){drawVectorArt(s);drawVectorTier(s);}s.vectorHP=s.hp;s.battle=newBattle({name:s.name,art:s.art,stats:s.stats,mastery:s.mastery,hp:s.stats.H,specialization:s.specialization,extreme:s.extreme,mode:s.summonMode},s.trainingSpec,{rng:s.rng,config:{supply:0,projection:true,hazard:!!s.hazard,ironPlayerDeath:!!s.iron}});s.phase='battle';s.vectorActive=true;return s.battle;}
export function depart(s){if(s.phase!=='camp')throw Error('不是准备阶段');s.days=0;s.phase='prep';s.nodeIntro=false;}
export function buyIntel(s){let key=nodeOf(s).id+'-'+s.battleIndex;if(s.intelBought===key)return;if(s.intel<1)throw Error('情报不足');s.intel--;s.intelBought=key;}
export function battleSpec(s){const spec=copy(nodeOf(s).battles[s.battleIndex]);if(s.solo){spec.allies=[];spec.solo=true;if(spec.id==='N06-4')spec.goal='击败塔露拉；或每轮完成防御/休整累计6点装置协同，并坚持至第8轮。';if(spec.id==='N12-4')spec.goal='破坏2个茧笼；或每轮完成防御/休整累计6点独立解缚，并坚持至第8轮。';}return spec;}
export function beginBattle(s){if(s.phase!=='prep')throw Error('不是战前阶段');let spec=battleSpec(s);s.battle=newBattle({name:s.name,art:s.art,stats:s.stats,hp:Math.max(1,Math.floor(s.hp)),mastery:s.mastery,specialization:s.specialization,extreme:s.extreme,mode:s.summonMode},spec,{rng:s.rng,config:{supply:s.supply,hazard:!!s.hazard&&s.mode!=='sandbox',ironPlayerDeath:!!s.iron&&s.mode!=='sandbox'}});for(let u of s.battle.units.filter(u=>u.side==='ally'&&u.npcId)){let old=s.allyHP?.[u.npcId];if(old)u.hp=Math.min(u.stats.H,Math.max(0,old.hp));}if(spec.id==='N06-4')for(let f of s.carriedCoolers||[])s.battle.units.push({...copy(f),id:'carried-'+f.id});s.rng=(s.rng+0x9e3779b9)>>>0;s.phase='battle';return s.battle;}
export function settle(s){const before=snapshot(s);let b=s.battle;if(s.phase!=='battle'||!b?.over)throw Error('尚未结束');const ironDeath=s.mode!=='sandbox'&&s.iron&&(b.over.kind==='ironDeath'||b.units.some(u=>u.isPlayer&&u.hp<=0));if(ironDeath)b.over={won:false,kind:'ironDeath',reason:'铁人模式：自身阵亡，本局结束'};if(s.vectorActive){const won=b.over.won,r=s.pendingTraining;s.rng=b.rng;s.hp=s.vectorHP;s.vectorActive=false;
 if(won){r.gains=growth(s,[0,1,2,3,4],Math.max(2,Math.floor(ANCHORS[r.enemyTier]*.045)),s.multiplier,s.id+':vector:'+s.day,'battle',r.enemyTier>=Math.floor(s.stats.rating.score)?2:0);r.mastery=Math.min(200-s.mastery,3+Math.floor(r.enemyTier/4));s.mastery+=r.mastery;r.masteryBase=3+Math.floor(r.enemyTier/4);r.masteryMultiplier=1;}
 s.hp=s.stats.H;r.recovered=true;r.won=won;r.reason=b.over.reason;r.record=battleRecord(b,s.day);s.dailyHistory.push(r);s.lastDaily=r;s.pendingTraining=null;s.battle=null;s.phase='camp';const result={...b.over,mastery:r.mastery,growth:r.gains,title:r.name,rounds:b.round,vector:true,before,after:snapshot(s)};if(won)s.pendingGrowth=result;if(ironDeath){s.phase='ending';s.ending='阵亡';s.endingReason=b.over.reason;s.lastResult=result;s.hp=0;delete s.pendingGrowth;}return result;}
 if(s.mode==='sandbox'){s.lastResult={...b.over,mastery:0,rounds:b.round,id:'SIM',title:b.spec.title};s.phase='result';return s.lastResult;}let key=b.spec.id+':'+(b.over.won?'win':'loss'),saved=s.ledger.includes(key);let p=b.units.find(u=>u.isPlayer),won=b.over.won;let deltaM=0;s.hp=Math.max(p.hp>0?1:0,Math.floor(p.hp/Math.max(1,p.stats.H)*s.stats.H));s.rng=b.rng;s.supply=b.supply;const rescued=won&&(p.hp<=0||p.removed);if(rescued)s.hp=Math.max(1,Math.floor(s.stats.H*.3));s.allyHP??={};for(let u of b.units.filter(u=>u.side==='ally'&&u.npcId))s.allyHP[u.npcId]={hp:Math.max(0,u.hp),max:u.stats.H};
 if(b.spec.id==='N06-3')s.carriedCoolers=b.units.filter(u=>u.facility&&u.side==='ally'&&u.hp>0&&!u.removed).map(copy);s.lastGrowth=[];if(!saved){s.ledger.push(key);let practice=Math.min(2,Object.keys(b.usage).length);let strength=Math.max(...b.units.filter(u=>u.side==='enemy'&&!u.owner&&!u.facility).map(u=>u.stats?.rating?.score||0));let base=won?(b.over.kind==='objective'?4:strength>=7?8:strength>=3?6:5):1;deltaM=Math.min(200-s.mastery,won?10:1,base+practice);s.mastery=Math.min(200,s.mastery+deltaM);
 const comparable=strength>=Math.floor(s.stats.rating.score)-1&&strength<=s.stats.rating.score+2;
 s.lastGrowth=won?growth(s,[0,1,2,3,4],Math.max(2,Math.min(ANCHORS[Math.floor(strength)]*.012,Math.min(...s.axes.map(a=>value(a.score)))*.05)),s.multiplier,key,'battle',b.over.kind==='victory'&&comparable?2:0):[];}
 if(rescued)s.hp=Math.max(1,Math.floor(s.stats.H*.3));if(won&&s.retried)s.nodeSuccess=nodeOf(s).battles.slice(0,s.battleIndex+1).every(v=>s.ledger.includes(v.id+':win'));if(!won){s.nodeSuccess=false;}
 s.lastResult={...b.over,mastery:deltaM,growth:s.lastGrowth||[],alreadyClaimed:saved,rescued,rescueHP:rescued?s.hp:0,rounds:b.round,id:key,title:b.spec.title,day:s.day,record:battleRecord(b,s.day),before,after:snapshot(s)};if(won&&!saved)s.pendingGrowth=s.lastResult;s.history.push(s.lastResult);s.phase='result';s.firstAid=false;
 if(!won)endStoryFailure(s);return s.lastResult;}
function endStoryFailure(s){s.phase='ending';s.nodeSuccess=false;s.reserved=0;delete s.pendingGrowth;s.ending=s.iron&&s.lastResult?.kind==='ironDeath'?'阵亡':s.battle&&!s.battle.units.some(v=>v.side==='ally'&&v.hp>0&&!v.removed&&!v.facility&&!v.relay)?'全队覆灭':'任务失败';s.endingReason=s.lastResult?.reason||'未达成本场作战目标';}
export function retry(){throw Error('剧情作战失败即结束本局，无法重试');}
export function nextBattle(s){if(s.mode==='sandbox'){s.hp=s.stats.H;s.phase='prep';s.battle=null;s.firstAid=false;return;}if(s.phase!=='result'||!s.lastResult.won)throw Error('无法进入下一战');if(s.battleIndex>=3){s.phase='nodeEnd';return;}s.battleIndex++;s.phase='prep';s.battle=null;}
export function evacuate(s){if(s.phase!=='result'||s.lastResult?.won!==false)throw Error('没有失败的剧情作战');endStoryFailure(s);}
export function nextNode(s){if(s.phase!=='nodeEnd')throw Error('尚未结算节点');if(s.nodeSuccess===false){endStoryFailure(s);return;}if(s.mode==='single'||s.nodeIndex>=11){s.phase='ending';s.ending=s.mode==='campaign'?(s.history.some(r=>!r.won&&!s.ledger.includes(r.id.split(':')[0]+':win'))?'旅程完成 · 含撤离记录':'任务完成'):s.nodeSuccess?'任务完成':'撤离';return;}s.nodeIndex++;enterNode(s);}
export function save(s,storage=globalThis.localStorage){storage.setItem(STORAGE_KEY,JSON.stringify(s));}
export function load(storage=globalThis.localStorage){let raw=storage.getItem(STORAGE_KEY);if(!raw)return null;let s=JSON.parse(raw);validateSave(s);refreshBattleCards(s);return s;}
export function validateSave(s){if(s?.version===1){s.version=2;s.iron=s.iron??false;s.legend=false;delete s.injury;delete s.manualAllies;delete s.plan;delete s.planClaimed;if(s.battle){s.battle.supply=s.supply;s.battle.config||={};for(const u of s.battle.units){u.cd.A=u.cd.B=0;u.cd.C=Math.min(u.cd.C||0,u.turn+1);delete u.aiKey;if(u.owner&&!u.facility&&!u.relay){const owner=s.battle.units.find(v=>v.id===u.owner);if(owner){const op=tuneSummon(owner,{name:u.name,h:u.stats.H/owner.stats.H,a:u.attack/Math.max(1,owner.stats.P),basis:u.attackBasis,taunt:u.taunt},[]),ratio=u.hp/u.stats.H;u.stats.H=Math.floor(owner.stats.H*op.h);u.hp=Math.floor(u.stats.H*ratio);u.attack=(op.basis==='A'?owner.stats.A:op.basis==='Q'?Math.max(owner.stats.A,owner.stats.P):owner.stats.P)*op.a;u.stats.A=u.stats.P=u.attack;u.stats.D=owner.stats.D*op.d;u.stats.R=owner.stats.R*op.r;u.stats.V=op.v;u.summonRole=op.role;}}}for(const owner of [...s.battle.units].filter(u=>u.npcId==='meph'||cardOf(u)?.passive.includes('hosts'))){owner.hostMaster=true;for(const u of s.battle.units.filter(u=>u.owner===owner.id))u.removed=true;for(const h of HOSTS)spawn(s.battle,owner,{op:'summon',...h});}}}if(s?.version===2){s.version=3;s.specialization='';s.extreme=false;if(s.stats&&s.axes.length===5){const hpRatio=s.hp/s.stats.H;s.stats=derive(s.axes.map(a=>a.score),s.identity);s.hp=Math.min(s.stats.H,Math.max(0,Math.floor(hpRatio*s.stats.H)));}if(s.battle)for(const u of s.battle.units){const ratio=u.stats.Emax?u.e/u.stats.Emax:0;if(!u.owner&&!u.eventBoss){u.stats.Emax=Math.max(u.stats.Emax,derive([0,0,0,0,score(u.stats.R)]).Emax);u.e=Math.floor(ratio*u.stats.Emax);}delete u.specialization;delete u.extreme;if(u.cardData?.variant){const base=BY_ID[u.cardData.baseArt];if(base)u.cardData=structuredClone(evolvedCard(base,u.mastery));}else if(u.npcId)u.cardData=npcCard(DATA.campaign.units.find(x=>x.id===u.npcId));}}if(!s||s.version!==VERSION||!Array.isArray(s.rolls)||!Array.isArray(s.axes)||typeof s.rng!=='number'||!['creation','confirm','camp','vectorPrep','prep','battle','result','nodeEnd','ending'].includes(s.phase))throw Error('不兼容的存档');if(s.solo!==undefined&&typeof s.solo!=='boolean')throw Error('存档模式不合法');s.solo=s.solo??false;if(s.hazard!==undefined&&typeof s.hazard!=='boolean')throw Error('险路恶敌模式不合法');s.hazard=s.hazard??false;if(s.art&&!BY_ID[s.art])throw Error('存档技艺不存在');if(s.axes.some(a=>!Number.isFinite(a.score)||a.score<0||a.score>16.999))throw Error('存档属性不合法');if(s.phase==='battle'){if(!s.battle||!Array.isArray(s.battle.units)||s.battle.units.length>150)throw Error('战斗存档不完整');for(let u of s.battle.units){if(!u.stats||['hp','e','gauge','turn'].some(k=>!Number.isFinite(u[k])||u[k]<0)||['H','A','P','D','R','V','Emax'].some(k=>!Number.isFinite(u.stats[k])||u.stats[k]<0)||!u.statuses||!Array.isArray(u.shields))throw Error('战斗存档数值不合法');}}if(s.phase==='battle'&&s.vectorActive&&s.battle?.spec.id==='VECTOR'){s.battle.scene.limit=120;s.battle.spec.goal='击败训练投影；博士退场后存活友方继续作战。120轮防僵局，18轮起力竭。';const b=s.battle;if(b.round<120&&b.over?.reason==='未在12轮内完成作战目标'&&b.units.some(u=>u.isPlayer&&u.hp>0&&!u.removed)&&b.units.some(u=>u.side==='enemy'&&!u.facility&&u.hp>0&&!u.removed))b.over=null;}if(s.phase==='battle'&&s.battle){s.battle.config??={};s.battle.config.ironPlayerDeath=!!s.iron&&s.mode!=='sandbox';if(s.battle.config.ironPlayerDeath&&s.battle.units.some(u=>u.isPlayer&&u.hp<=0))s.battle.over={won:false,kind:'ironDeath',reason:'铁人模式：自身阵亡，本局结束'};}if(s.phase==='battle'&&s.battle?.over?.reason==='你已倒下，行动终止'&&s.battle.units.some(v=>v.side==='ally'&&v.hp>0&&!v.removed&&!v.facility&&!v.relay))s.battle.over=null;if(s.mode!=='sandbox'&&!s.vectorActive&&((s.phase==='result'&&s.lastResult?.won===false)||(s.phase==='nodeEnd'&&s.nodeSuccess===false)))endStoryFailure(s);return true;}

export function createSandbox({art='AK002',tier=3,mastery=200,enemy='soldier',mode=0}={}){
 if(!BY_ID[art]||!Number.isInteger(tier)||tier<0||tier>16||![0,100,200].includes(mastery)||!DATA.campaign.units.some(u=>u.id===enemy))throw Error('模拟参数不合法');
 let s=createRun({name:'博士',seed:'simulation-'+Date.now(),mode:'sandbox',node:'N01'});s.axes=Array(5).fill(0).map(()=>newAxis(tier));s.identity='I02';s.art=art;s.mastery=mastery;s.multiplier=1;s.talent='B+';s.stats=derive(Array(5).fill(tier));s.hp=s.stats.H;s.summonMode=mode;s.phase='prep';s.rolls=[{name:'PRTS'},{name:'模拟数据'},{name:'非感染者'}];s.allyHP={};s.trainingSpec={id:'SIM',title:'模拟作战 · '+BY_ID[art].name,allies:[],enemies:[enemy],goal:'击败模拟敌人，或查看本次战术结果。',mechanic:'模拟不会消耗旅程补给，也不会增加正式角色熟练度。'};return s;
}

export const snapshot=s=>({stats:{...s.stats},mastery:s.mastery,rating:s.stats.rating.name});
export function continueGrowth(s){if(!s.pendingGrowth)throw Error('没有待确认的成长');const vector=s.pendingGrowth.vector;delete s.pendingGrowth;if(vector)return;if(s.phase!=='result')throw Error('结算状态异常');nextBattle(s);if(s.phase==='prep')beginBattle(s);else if(s.phase==='nodeEnd')nextNode(s);}

export function refreshBattleCards(s){if(!s.battle)return;for(const u of s.battle.units){const base=BY_ID[u.cardData?.baseArt||u.card];if(!base)continue;const card=evolvedCard(base,u.mastery||0);u.card=card.id;u.cardData=card.variant?structuredClone(card):null;u.cap=card.cap;u.res=Math.max(0,Math.min(card.cap,u.res||0));}}
